stants.int"><strong><span>{@link Swoole\Redis\Server::INT}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="swoole-redis-server.constants.string"><strong><span>{@link Swoole\Redis\Server::STRING}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="swoole-redis-server.constants.set"><strong><span>{@link Swoole\Redis\Server::SET}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="swoole-redis-server.constants.map"><strong><span>{@link Swoole\Redis\Server::MAP}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Swoole\Redis\Server::format} — Description</li><li>{@link Swoole\Redis\Server::setHandler} — Description</li><li>{@link Swoole\Redis\Server::start} — Description</li></ul></div>
